
from pathlib import Path
import pandas as pd
from pyproj import Geod

REPORT_DIR = Path("member1_preprocessing/outputs/reports")

# Load the reports generated by our previous script
gaps = pd.read_csv(REPORT_DIR / "large_timestamp_gaps.csv")
routes = pd.read_csv(REPORT_DIR / "disconnected_route_pairs.csv")

# ----------------------------------------
# 1. Analyse spatial movement during gaps
# ----------------------------------------

geod = Geod(ellps="WGS84")

distances = []
average_speeds = []

for _, row in gaps.iterrows():

    _, _, distance = geod.inv(
        row["previous_longitude"],
        row["previous_latitude"],
        row["current_longitude"],
        row["current_latitude"]
    )

    gap = row["gap_seconds"]

    distances.append(distance)

    if gap > 0:
        average_speeds.append(
            distance / gap * 3.6
        )
    else:
        average_speeds.append(float("nan"))

gaps["distance_between_points_m"] = distances
gaps["average_speed_across_gap_kmh"] = average_speeds

# Save enriched gap report
gaps.to_csv(
    REPORT_DIR / "large_timestamp_gaps_analyzed.csv",
    index=False
)

# ----------------------------------------
# 2. Group gaps by duration
# ----------------------------------------

gap_bins = [5, 10, 30, 60, 300, 3600, float("inf")]

gap_labels = [
    "5-10 seconds",
    "10-30 seconds",
    "30-60 seconds",
    "1-5 minutes",
    "5-60 minutes",
    "1 hour or more"
]

gaps["gap_category"] = pd.cut(
    gaps["gap_seconds"],
    bins=gap_bins,
    labels=gap_labels,
    right=False
)

print("\nGAP DISTRIBUTION")
print("================")

print(
    gaps["gap_category"]
    .value_counts(sort=False)
    .to_string()
)

# ----------------------------------------
# 3. Largest spatial jumps
# ----------------------------------------

print("\nLARGEST SPATIAL JUMPS")
print("=====================")

print(
    gaps.nlargest(10, "distance_between_points_m")[
        [
            "trip_id",
            "gap_seconds",
            "distance_between_points_m",
            "average_speed_across_gap_kmh"
        ]
    ].to_string(index=False)
)

# ----------------------------------------
# 4. Gap counts per trip
# ----------------------------------------

print("\nGAPS PER TRIP")
print("=============")

print(
    gaps.groupby("trip_id").size()
    .sort_values(ascending=False)
    .head(15)
    .to_string()
)

# ----------------------------------------
# 5. Exact disconnected route pairs
# ----------------------------------------

print("\nDISCONNECTED ROUTE PAIRS")
print("========================")

if len(routes):
    print(
        routes[
            [
                "trip_id",
                "previous_route_position",
                "next_route_position",
                "previous_arc_id",
                "next_arc_id",
                "previous_end_node",
                "next_start_node"
            ]
        ].to_string(index=False)
    )
else:
    print("No disconnected route pairs.")

print("\nAnalysis completed.")
